-- Run explicitly in the dedicated kcat_rag database. No business table access.
CREATE TABLE IF NOT EXISTS rag_external_binding (job_id VARCHAR(36) PRIMARY KEY, task_id VARCHAR(64) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS rag_parent (build_id VARCHAR(36) NOT NULL, parent_id VARCHAR(64) NOT NULL, context_json LONGTEXT NOT NULL, PRIMARY KEY(build_id,parent_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS rag_job (job_id VARCHAR(36) PRIMARY KEY, snapshot_id VARCHAR(36) NOT NULL, drama_id VARCHAR(32) NOT NULL, source_version BIGINT NOT NULL, pipeline_version VARCHAR(80) NOT NULL, profile VARCHAR(80) NOT NULL, build_id VARCHAR(36) NOT NULL, state VARCHAR(32) NOT NULL, owner VARCHAR(80), lease_until DOUBLE NOT NULL DEFAULT 0, fence BIGINT NOT NULL DEFAULT 0, attempts INT NOT NULL DEFAULT 0, next_attempt DOUBLE NOT NULL DEFAULT 0, error VARCHAR(80), progress VARCHAR(100), UNIQUE(drama_id, source_version, pipeline_version, profile)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS rag_stage (job_id VARCHAR(36) NOT NULL, stage_key VARCHAR(200) NOT NULL, input_hash VARCHAR(64) NOT NULL, result_json LONGTEXT NOT NULL, PRIMARY KEY(job_id, stage_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS rag_document (chunk_id VARCHAR(64) PRIMARY KEY, build_id VARCHAR(36) NOT NULL, parent_id VARCHAR(64) NOT NULL, document_json LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS rag_build (build_id VARCHAR(36) PRIMARY KEY, job_id VARCHAR(36) NOT NULL, profile VARCHAR(80) NOT NULL, state VARCHAR(32) NOT NULL, manifest_json LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS rag_session (session_id VARCHAR(36) PRIMARY KEY, query_hash VARCHAR(64) NOT NULL, page_size INT NOT NULL, expires DOUBLE NOT NULL, result_json LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
